import sys
import os
import re
import html
import subprocess
import json
import xml.etree.ElementTree as ET
from datetime import datetime, timezone, timedelta
import email.utils

UA = "Mozilla/5.0 (compatible; OpenClawScout/1.0)"

FEEDS = [
    {"name": "CoinDesk", "url": "https://www.coindesk.com/arc/outboundfeeds/rss/"},
    {"name": "CoinTelegraph", "url": "https://cointelegraph.com/rss"},
    {"name": "Decrypt", "url": "https://decrypt.co/feed"},
    {"name": "Google News", "url": "https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en"},
    {"name": "BeInCrypto", "url": "https://beincrypto.com/feed/"},
    {"name": "The Block", "url": "https://www.theblock.co/rss.xml"},
    {"name": "CryptoSlate", "url": "https://cryptoslate.com/feed/"},
    {"name": "CryptoFox", "url": "https://cryptofox.news/rss/markets/"},
    {"name": "CryptoFox", "url": "https://cryptofox.news/rss/regulation/"}
]

PRIORITY = {
    "coindesk": 10,
    "cointelegraph": 9,
    "decrypt": 8,
    "the block": 7,
    "beincrypto": 6,
    "cryptoslate": 5,
    "cryptofox": 4,
    "google news": 3
}

def clean_html(text):
    if not text:
        return ""
    text = re.sub(r'<[^>]+>', '', text)
    text = html.unescape(text)
    text = " ".join(text.split())
    return text

def parse_date(date_str):
    if not date_str:
        return None
    date_str = date_str.strip()
    try:
        dt = email.utils.parsedate_to_datetime(date_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        pass
    try:
        if date_str.endswith('Z'):
            date_str = date_str[:-1] + '+00:00'
        dt = datetime.fromisoformat(date_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        pass
    return None

def get_significant_words(text):
    stop_words = {'a', 'an', 'the', 'and', 'or', 'but', 'is', 'are', 'was', 'were', 'to', 'for', 'in', 'on', 'at', 'by', 'with', 'of', 'about', 'as', 'from', 'into', 'with', 'this', 'that', 'it', 'its', 'has', 'have', 'had', 'been', 'be', 'will', 'would', 'should', 'can', 'could', 'may', 'might', 'must'}
    words = []
    cleaned = ''.join(c if c.isalnum() else ' ' for c in text.lower())
    for w in cleaned.split():
        if w not in stop_words and len(w) > 1:
            words.append(w)
    return set(words)

def near_identical(words1, words2):
    if not words1 or not words2:
        return False
    intersection = words1.intersection(words2)
    overlap = len(intersection) / max(len(words1), len(words2))
    return overlap >= 0.80

def matches_meme_filter(headline):
    meme_words = ["dogecoin", "shiba", "pepe", "floki", "bonk", "wif", "memecoin", "meme coin"]
    headline_lower = headline.lower()
    for mw in meme_words:
        if mw in headline_lower:
            return True
    return False

def is_valid_url(url):
    if not url:
        return False
    url_lower = url.lower().strip()
    if url_lower.startswith('mailto:') or url_lower.startswith('javascript:'):
        return False
    return True

def fetch_feed(feed):
    print(f"Fetching {feed['name']} from {feed['url']}...")
    try:
        # Run curl with the proper User-Agent and timeout
        cmd = ["curl", "-sL", "-A", UA, feed["url"], "--max-time", "12"]
        res = subprocess.run(cmd, capture_output=True, text=False, timeout=15)
        if res.returncode != 0:
            print(f"Error fetching {feed['name']}: curl returned code {res.returncode}")
            return b""
        return res.stdout
    except subprocess.TimeoutExpired:
        print(f"Timeout fetching {feed['name']}")
        return b""
    except Exception as e:
        print(f"Exception fetching {feed['name']}: {e}")
        return b""

def parse_feed_xml(xml_bytes, feed_name, sequence_start):
    if not xml_bytes:
        return []
    try:
        root = ET.fromstring(xml_bytes)
    except Exception as e:
        print(f"Error parsing XML for {feed_name}: {e}")
        return []

    # Find item elements (supporting Atom and RSS formats)
    items = []
    # Let's find tags robustly
    item_elems = []
    for elem in root.iter():
        local_tag = elem.tag.split('}')[-1] if '}' in elem.tag else elem.tag
        if local_tag in ('item', 'entry'):
            item_elems.append(elem)

    feed_items = []
    for idx, item_elem in enumerate(item_elems):
        headline = ""
        url = ""
        pub_date_str = ""
        summary = ""

        # Extract sub-tags robustly
        for child in item_elem:
            local_tag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
            if local_tag == 'title':
                headline = clean_html(child.text or "")
            elif local_tag == 'link':
                if 'href' in child.attrib:
                    url = child.attrib['href'].strip()
                elif child.text:
                    url = child.text.strip()
            elif local_tag in ('pubDate', 'published', 'updated', 'date'):
                pub_date_str = child.text or ""
            elif local_tag in ('description', 'summary', 'content'):
                summary = clean_html(child.text or "")

        # If link wasn't found in link element, let's search for GUID/ID if it looks like a URL
        if not url:
            for child in item_elem:
                local_tag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
                if local_tag in ('guid', 'id') and child.text and child.text.startswith('http'):
                    url = child.text.strip()

        # Clean Google News URLs
        # Instruction: "strip Google News redirect wrappers if present; the original publisher URL is preferred"
        # However, Google News RSS uses a complex redirection. Let's see if there is any simple fallback, but we'll leave it as is if none.

        feed_items.append({
            "feed_index": idx,
            "headline": headline,
            "url": url,
            "pub_date_str": pub_date_str,
            "summary": summary[:280] if summary else "",
            "source": feed_name,
            "seq": sequence_start + idx
        })
    return feed_items

def check_history(url):
    try:
        res = subprocess.run(
            ["bash", "/home/bhard/.openclaw/workspace-researcher/skills/history/article_history.sh", "check", url],
            capture_output=True,
            text=True,
            check=True
        )
        output = res.stdout.strip()
        if "EXISTS" in output:
            return False
        return True
    except Exception as e:
        print(f"Error checking history for {url}: {e}")
        return True

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 scan_headlines.py <output_file> <target_count>")
        sys.exit(1)

    output_file = sys.argv[1]
    target_count = int(sys.argv[2])

    now = datetime.now(timezone.utc)
    twenty_four_hours_ago = now - timedelta(hours=24)

    # 1. Fetch and Parse Feeds
    all_raw_items = []
    seq = 0
    for feed in FEEDS:
        xml_bytes = fetch_feed(feed)
        items = parse_feed_xml(xml_bytes, feed["name"], seq)
        all_raw_items.extend(items)
        seq += len(items)

    print(f"Total raw items parsed: {len(all_raw_items)}")

    # 2. Filter raw items
    filtered_items = []
    for item in all_raw_items:
        # Validate URL
        if not is_valid_url(item["url"]):
            continue

        # Parse date
        parsed_dt = parse_date(item["pub_date_str"])
        item["parsed_dt"] = parsed_dt

        # Hard filters before keeping an item:
        # 1. pub_date must parse to a timestamp within the last 24 hours.
        # If we cannot parse pub_date for a feed, keep it only if it is among the very first 5 items of that feed.
        is_fresh = False
        if parsed_dt:
            if parsed_dt >= twenty_four_hours_ago:
                is_fresh = True
        else:
            if item["feed_index"] < 5:
                is_fresh = True

        if not is_fresh:
            continue

        filtered_items.append(item)

    print(f"After basic <redacted> and URL filters: {len(filtered_items)}")

    # Meme filters: drop items whose headline matches the meme-only filter unless cross-covered
    final_filtered_items = []
    for item in filtered_items:
        if matches_meme_filter(item["headline"]):
            # Check cross-coverage
            major_sources = {"coindesk", "cointelegraph", "decrypt", "beincrypto", "the block"}
            matching_major_sources = set()
            if item["source"].lower() in major_sources:
                matching_major_sources.add(item["source"].lower())

            item_words = get_significant_words(item["headline"])
            for other in filtered_items:
                if other is item:
                    continue
                if other["source"].lower() not in major_sources:
                    continue
                other_words = get_significant_words(other["headline"])
                if near_identical(item_words, other_words):
                    matching_major_sources.add(other["source"].lower())

            if len(matching_major_sources) >= 2:
                # Keep cross-covered meme-coin story
                final_filtered_items.append(item)
            else:
                # Drop meme-only story
                continue
        else:
            final_filtered_items.append(item)

    print(f"After meme filters: {len(final_filtered_items)}")

    # 3. Deduplicate
    # Deduplicate same URL or same-story (near-identical headlines)
    # Keeping the one from the higher-priority source.
    unique_items = deduplicate_items(final_filtered_items)
    print(f"After deduplication: {len(unique_items)}")

    # 4. History Gate Check
    surviving_candidates = []
    for item in unique_items:
        if check_history(item["url"]):
            surviving_candidates.append(item)
        else:
            print(f"Dropped by history gate: {item['headline']} ({item['url']})")

    print(f"After history gate: {len(surviving_candidates)}")

    # 5. Sorting and Trim
    # Sort survivors: pub_date desc.
    # For items missing parsed_dt, place them after dated items in the order you saw them (using seq).
    dated_items = [x for x in surviving_candidates if x["parsed_dt"] is not None]
    undated_items = [x for x in surviving_candidates if x["parsed_dt"] is None]

    dated_items.sort(key=lambda x: x["parsed_dt"], reverse=True)
    undated_items.sort(key=lambda x: x["seq"])

    sorted_candidates = dated_items + undated_items

    # Keep at most target_count
    final_candidates = sorted_candidates[:target_count]

    # Format output items
    candidates_output = []
    for idx, item in enumerate(final_candidates):
        pub_date_iso = item["parsed_dt"].isoformat() if item["parsed_dt"] else item["pub_date_str"]
        candidates_output.append({
            "candidate_index": idx + 1,
            "headline": item["headline"],
            "url": item["url"],
            "pub_date": pub_date_iso,
            "source": item["source"],
            "summary": item["summary"],
            "corroborating_sources": item.get("corroborating_sources", [])
        })

    # Prepare JSON output
    scanned_at_iso = datetime.now(timezone.utc).isoformat()
    output_data = {
        "status": "ok",
        "mode": "headline_scan",
        "scanned_at": scanned_at_iso,
        "target_count": target_count,
        "candidate_count": len(candidates_output),
        "candidates": candidates_output
    }

    # Write to target file
    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(output_data, f, indent=2)

    print(f"Successfully wrote {len(candidates_output)} candidates to {output_file}")

def deduplicate_items(items):
    # Sort items first by priority descending so that the first one we process from a cluster is the highest priority
    sorted_items = sorted(items, key=lambda x: PRIORITY.get(x['source'].lower(), 0), reverse=True)

    unique_items = []
    for item in sorted_items:
        match_idx = -1
        for idx, unique in enumerate(unique_items):
            if unique['url'] == item['url']:
                match_idx = idx
                break
            if near_identical(get_significant_words(unique['headline']), get_significant_words(item['headline'])):
                match_idx = idx
                break

        if match_idx != -1:
            unique = unique_items[match_idx]
            if unique['url'] != item['url']:
                # Same-story dedupe (different URL, near-identical headline)
                if 'corroborating_sources' not in unique:
                    unique['corroborating_sources'] = []
                if len(unique['corroborating_sources']) < 2:
                    if not any(cs['url'] == item['url'] for cs in unique['corroborating_sources']):
                        unique['corroborating_sources'].append({
                            "source": item['source'],
                            "url": item['url']
                        })
        else:
            item['corroborating_sources'] = []
            unique_items.append(item)

    return unique_items

if __name__ == "__main__":
    main()
